    public static func resolve(_ name: String, id: Int64? = nil, secondaryId: Int64? = nil) throws -> ServiceEndpoint {
        guard let route = routes[name] else { throw ServiceError(status: 400, code: "UNKNOWN_ENDPOINT") }
        var path = route.path
        if path.contains("{id}") { guard let id, id > 0, id <= 9_007_199_254_740_991 else { throw ServiceError(status: 400, code: "INVALID_ID") }; path = path.replacingOccurrences(of: "{id}", with: String(id)) }
        if path.contains("{secondaryId}") { guard let secondaryId, secondaryId > 0, secondaryId <= 9_007_199_254_740_991 else { throw ServiceError(status: 400, code: "INVALID_ID") }; path = path.replacingOccurrences(of: "{secondaryId}", with: String(secondaryId)) }
        return ServiceEndpoint(path: path, method: route.method, csrf: route.csrf)
    }
